inst._zod.parse = (payload, ctx) => {
  const n = size(payload.value);
  if (n > cap && !ctx?.skipChecks && ctx?.direction !== "backward") {
    for (const [max, ch] of util.sizeCaps(inst._zod.def.checks)) {
      if (n > max && ch._zod.def.when!(payload)) {
        const start = payload.issues.length;
        ch._zod.check(payload as ParsePayload<never>);
        // the value is still the raw input, so no later check may read it
        (payload.issues[start] as { continue?: boolean }).continue = false;
        util.attachSchema(payload.issues, start, inst);
        return payload;
      }
    }
  }
  return parse(payload, ctx);
};

function inputOptin(schema: schemas.$ZodType): "optional" | "defaulted" | undefined {
  const def = schema._zod.def;
  if (def.type === "pipe" && (def as schemas.$ZodPipeDef).in._zod.traits.has("$ZodTransform")) {
    return inputOptin((def as schemas.$ZodPipeDef).out);
  }
  if (def.type === "catch") {
    return inputOptin((def as schemas.$ZodCatchDef).innerType);
